#include <stdio.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <unistd.h>
#include <stdlib.h>
#include <sys/wait.h>

void print_maxrss(const char* msg) {
    struct rusage usage;
    getrusage(RUSAGE_CHILDREN, &usage);
    printf("%s Max RSS: %ld KB\n", msg, usage.ru_maxrss);
}

int main() {
    print_maxrss("Before:");
    if (fork() == 0) {
        void* p = malloc(10 * 1024 * 1024);
        for (int i = 0; i < 10 * 1024 * 1024; i += 4096) ((char*)p)[i] = 1;
        exit(0);
    }
    wait(NULL);
    print_maxrss("After 10MB child:");
    if (fork() == 0) {
        void* p = malloc(20 * 1024 * 1024);
        for (int i = 0; i < 20 * 1024 * 1024; i += 4096) ((char*)p)[i] = 1;
        exit(0);
    }
    wait(NULL);
    print_maxrss("After 20MB child:");
    return 0;
}
EOF
