#include <stdio.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <unistd.h>
#include <stdlib.h>
#include <sys/wait.h>
#include <string.h>

int main() {
    for (int i = 1; i <= 3; i++) {
        pid_t pid = fork();
        if (pid == 0) {
            size_t size = i * 10 * 1024 * 1024;
            void* p = malloc(size);
            memset(p, 1, size);
            _exit(0);
        }
        struct rusage usage;
        wait4(pid, NULL, 0, &usage);
        printf("Child %d: Max RSS = %ld KB\n", i, usage.ru_maxrss);
    }
    return 0;
}
