{"command":"cat <<'EOF' > src/main.rs
use std::env;
use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use std::io::{self, Write};

#[repr(C)]
#[derive(Debug, Copy, Clone)]
pub struct timeval {
    pub tv_sec: i64,
    pub tv_usec: i64,
}

#[repr(C)]
#[derive(Debug, Copy, Clone)]
pub struct rusage {
    pub ru_utime: timeval,
    pub ru_stime: timeval,
    pub ru_maxrss: i64,
    pub ru_ixrss: i64,
    pub ru_idrss: i64,
    pub ru_isrss: i64,
    pub ru_minflt: i64,
    pub ru_majflt: i64,
    pub ru_nswap: i64,
    pub ru_inblock: i64,
    pub ru_oublock: i64,
    pub ru_msgsnd: i64,
    pub ru_msgrcv: i64,
    pub ru_nsignals: i64,
    pub ru_nvcsw: i64,
    pub ru_nivcsw: i64,
}

extern "C" {
    fn wait4(pid: i32, status: *mut i32, options: i32, rusage: *mut rusage) -> i32;
}

#[derive(Default)]
struct Options {
    commands: Vec<String>,
    warmup: u64,
    min_runs: Option<u64>,
    max_runs: Option<u64>,
    runs: Option<u64>,
    setup: Option<String>,
    prepare: Vec<String>,
    conclude: Vec<String>,
    cleanup: Option<String>,
    shell: Option<String>,
    ignore_failure: bool,
    style: String,
    sort: String,
    time_unit: Option<String>,
    export_json: Option<String>,
    export_csv: Option<String>,
    export_markdown: Option<String>,
    export_asciidoc: Option<String>,
    export_orgmode: Option<String>,
    show_output: bool,
    command_names: Vec<String>,
    parameter_scan: Option<(String, f64, f64, f64)>,
    parameter_lists: Vec<(String, Vec<String>)>,
}

fn print_help() {
    let help_text = r#"A command-line benchmarking tool.

Usage: executable [OPTIONS] <command>...

Arguments:
  <command>...
          The command to benchmark.

Options:
  -w, --warmup <NUM>
          Perform NUM warmup runs before the actual benchmark.
  -m, --min-runs <NUM>
          Perform at least NUM runs for each command (default: 10).
  -M, --max-runs <NUM>
          Perform at most NUM runs for each command.
  -r, --runs <NUM>
          Perform exactly NUM runs for each command.
  -s, --setup <CMD>
          Execute CMD before each set of timing runs.
  -p, --prepare <CMD>
          Execute CMD before each timing run.
  -C, --conclude <CMD>
          Execute CMD after each timing run.
  -c, --cleanup <CMD>
          Execute CMD after completion of all benchmarking runs.
  -P, --parameter-scan <VAR> <MIN> <MAX>
          Perform benchmark runs for each value in the range MIN..MAX.
  -D, --parameter-step-size <DELTA>
          Traverse the range MIN..MAX in steps of DELTA.
  -L, --parameter-list <VAR> <VALUES>
          Perform benchmark runs for each value in the comma-separated list VALUES.
  -S, --shell <SHELL>
          Set the shell to use for executing benchmarked commands.
  -N
          An alias for '--shell=none'.
  -i, --ignore-failure
          Ignore failures of the benchmarked programs.
      --style <TYPE>
          Set output style type (default: auto). [basic, full, nocolor, color, none]
      --sort <METHOD>
          Specify the sort order: [auto, command, mean-time]
  -u, --time-unit <UNIT>
          Set the time unit: [microsecond, millisecond, second]
      --export-asciidoc <FILE>
      --export-csv <FILE>
      --export-json <FILE>
      --export-markdown <FILE>
      --export-orgmode <FILE>
      --show-output
          Print the stdout and stderr of the benchmark.
  -n, --command-name <NAME>
          Give a meaningful name to a command.
  -h, --help
          Print help
  -V, --version
          Print version"#;
    println!("{}", help_text);
}

fn main() {
    let mut options = Options {
        style: "auto".to_string(),
        sort: "auto".to_string(),
        ..Default::default()
    };
    let mut args = env::args().skip(1).peekable();
    let mut parameter_step_size: Option<f64> = None;

    while let Some(arg) = args.next() {
        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                return;
            }
            "-V" | "--version" => {
                println!("hyperfine 1.20.0");
                return;
            }
            "-w" | "--warmup" => {
                options.warmup = args.next().expect("Missing value").parse().expect("Invalid number");
            }
            "-m" | "--min-runs" => {
                options.min_runs = Some(args.next().expect("Missing value").parse().expect("Invalid number"));
            }
            "-M" | "--max-runs" => {
                options.max_runs = Some(args.next().expect("Missing value").parse().expect("Invalid number"));
            }
            "-r" | "--runs" => {
                options.runs = Some(args.next().expect("Missing value").parse().expect("Invalid number"));
            }
            "-s" | "--setup" => {
                options.setup = Some(args.next().expect("Missing value"));
            }
