    } else {
        let mut c = Command::new("/bin/sh");
        c.arg("-c");
        c.arg(cmd_str);
        c
    };

    if !show_output {
        command.stdout(Stdio::null());
        command.stderr(Stdio::null());
    }

    let start = Instant::now();
    let mut child = match command.spawn() {
        Ok(c) => c,
        Err(_) => return RunResult { exit_code: -1, ..Default::default() },
    };
    let pid = child.id() as i32;

    let mut status: i32 = 0;
    let mut usage = rusage::default();
    unsafe {
        wait4(pid, &mut status, 0, &mut usage);
    }
    let duration = start.elapsed();

    RunResult {
        wall_time: duration.as_secs_f64(),
        user_time: usage.ru_utime.tv_sec as f64 + usage.ru_utime.tv_usec as f64 / 1_000_000.0,
        system_time: usage.ru_stime.tv_sec as f64 + usage.ru_stime.tv_usec as f64 / 1_000_000.0,
        max_rss: usage.ru_maxrss as u64 * 1024,
        exit_code: if status & 0x7F == 0 { (status >> 8) & 0xFF } else { -1 },
    }
}

fn calibrate_shell(shell: &Option<String>, show_output: bool) -> RunResult {
    let mut total_wall = 0.0;
    let mut total_user = 0.0;
    let mut total_system = 0.0;
    let num_runs = 50;
    for _ in 0..num_runs {
        let res = run_command("", shell, show_output);
        total_wall += res.wall_time;
        total_user += res.user_time;
        total_system += res.system_time;
    }
    RunResult {
        wall_time: total_wall / num_runs as f64,
        user_time: total_user / num_runs as f64,
        system_time: total_system / num_runs as f64,
        max_rss: 0,
        exit_code: 0,
    }
}

fn expand_parameters(options: &Options) -> Vec<(String, String)> {
    let mut result = Vec::new();
    if let Some((var, min, max, step)) = &options.parameter_scan {
        let mut curr = *min;
        while curr <= *max + step / 1_000_000.0 {
            let val = format!("{}", curr);
            for cmd in &options.commands {
                let expanded = cmd.replace(&format!("{{{}}}", var), &val);
                let name = if options.command_names.len() > result.len() {
                    options.command_names[result.len()].clone()
                } else {
                    expanded.clone()
                };
                result.push((expanded, name));
            }
            curr += step;
        }
    } else if !options.parameter_lists.is_empty() {
        let mut combinations = vec![HashMap::new()];
        for (var, values) in &options.parameter_lists {
            let mut new_combinations = Vec::new();
            for val in values {
                for combo in &combinations {
                    let mut new_combo: HashMap<String, String> = combo.clone();
                    new_combo.insert(var.clone(), val.clone());
                    new_combinations.push(new_combo);
                }
            }
            combinations = new_combinations;
        }
        for combo in combinations {
            for cmd in &options.commands {
                let mut expanded = cmd.clone();
                for (var, val) in &combo {
                    expanded = expanded.replace(&format!("{{{}}}", var), val);
                }
                let name = if options.command_names.len() > result.len() {
                    options.command_names[result.len()].clone()
                } else {
                    expanded.clone()
                };
                result.push((expanded, name));
            }
        }
    } else {
        for (i, cmd) in options.commands.iter().enumerate() {
            let name = if options.command_names.len() > i {
                options.command_names[i].clone()
            } else {
                cmd.clone()
            };
            result.push((cmd.clone(), name));
        }
    }
    result
}

fn main() {
    let mut options = Options {
        style: "auto".to_string(),
        sort: "auto".to_string(),
        ..Default::default()
    };
    let mut args = env::args().skip(1).peekable();
    let mut parameter_step_size: Option<f64> = None;

    while let Some(arg) = args.next() {
        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                return;
            }
            "-V" | "--version" => {
                println!("hyperfine 1.20.0");
                return;
            }
            "-w" | "--warmup" => {
                options.warmup = args.next().expect("Missing value").parse().expect("Invalid number");
            }
            "-m" | "--min-runs" => {
                options.min_runs = Some(args.next().expect("Missing value").parse().expect("Invalid number"));
            }
            "-M" | "--max-runs" => {
                options.max_runs = Some(args.next().expect("Missing value").parse().expect("Invalid number"));
            }
            "-r" | "--runs" => {
                options.runs = Some(args.next().expect("Missing value").parse().expect("Invalid number"));
            }
            "-s" | "--setup" => {
                options.setup = Some(args.next().expect("Missing value"));
            }
            "-p" | "--prepare" => {
                options.prepare.push(args.next().expect("Missing value"));
            }
            "-C" | "--conclude" => {
                options.conclude.push(args.next().expect("Missing value"));
            }
            "-c" | "--cleanup" => {
                options.cleanup = Some(args.next().expect("Missing value"));
            }
            "-P" | "--parameter-scan" => {
                let var = args.next().expect("Missing var");
                let min = args.next().expect("Missing min").parse().expect("Invalid min");
                let max = args.next().expect("Missing max").parse().expect("Invalid max");
                options.parameter_scan = Some((var, min, max, 1.0));
            }
            "-D" | "--parameter-step-size" => {
                parameter_step_size = Some(args.next().expect("Missing value").parse().expect("Invalid number"));
            }
            "-L" | "--parameter-list" => {
                let var = args.next().expect("Missing var");
                let values = args.next().expect("Missing values").split(',').map(|s| s.to_string()).collect();
                options.parameter_lists.push((var, values));
            }
            "-S" | "--shell" => {
                options.shell = Some(args.next().expect("Missing value"));
            }
            "-N" => {
                options.shell = Some("none".to_string());
            }
            "-i" | "--ignore-failure" => {
                options.ignore_failure = true;
            }
            "--style" => {
                options.style = args.next().expect("Missing value");
            }
            "--sort" => {
                options.sort = args.next().expect("Missing value");
            }
            "-u" | "--time-unit" => {
                options.time_unit = Some(args.next().expect("Missing value"));
            }
            "--export-asciidoc" => {
                options.export_asciidoc = Some(args.next().expect("Missing value"));
            }
            "--export-csv" => {
                options.export_csv = Some(args.next().expect("Missing value"));
            }
            "--export-json" => {
                options.export_json = Some(args.next().expect("Missing value"));
            }
            "--export-markdown" => {
                options.export_markdown = Some(args.next().expect("Missing value"));
            }
            "--export-orgmode" => {
                options.export_orgmode = Some(args.next().expect("Missing value"));
            }
            "--show-output" => {
                options.show_output = true;
            }
            "-n" | "--command-name" => {
                options.command_names.push(args.next().expect("Missing value"));
            }
            _ => {
                if !arg.starts_with('-') {
                    options.commands.push(arg);
                }
            }
        }
    }

    if let Some(step) = parameter_step_size {
        if let Some((var, min, max, _)) = options.parameter_scan.take() {
            options.parameter_scan = Some((var, min, max, step));
        }
    }

    if options.commands.is_empty() {
        print_help();
        return;
    }

    run_benchmarks(options);
}

fn run_benchmarks(options: Options) {
    let commands = expand_parameters(&options);
    let mut results = Vec::new();

    let use_color = options.style != "basic" && options.style != "nocolor" && options.style != "none";

    let shell_overhead = if options.shell.as_deref() != Some("none") {
        calibrate_shell(&options.shell, options.show_output)
    } else {
        RunResult::default()
    };

    for (i, (cmd_str, name)) in commands.iter().enumerate() {
        if use_color {
            print!("\x1b[1mBenchmark \x1b[0m\x1b[1m{}\x1b[0m: {}\n", i + 1, name);
        } else {
            println!("Benchmark {}: {}", i + 1, name);
        }
        io::stdout().flush().unwrap();

        if let Some(setup_cmd) = &options.setup {
            run_command(setup_cmd, &options.shell, options.show_output);
        }

        let prep_cmd = if options.prepare.len() == 1 {
            Some(&options.prepare[0])
        } else if i < options.prepare.len() {
            Some(&options.prepare[i])
        } else {
            None
        };

        let conclude_cmd = if options.conclude.len() == 1 {
            Some(&options.conclude[0])
        } else if i < options.conclude.len() {
            Some(&options.conclude[i])
        } else {
            None
        };

        for _ in 0..options.warmup {
            if let Some(p) = prep_cmd { run_command(p, &options.shell, options.show_output); }
            run_command(cmd_str, &options.shell, options.show_output);
            if let Some(c) = conclude_cmd { run_command(c, &options.shell, options.show_output); }
        }

        let mut run_times = Vec::new();
        let start_total = Instant::now();
        let min_runs = options.runs.unwrap_or(options.min_runs.unwrap_or(10));
        let mut run_count = 0;

        while run_count < min_runs || (options.runs.is_none() && start_total.elapsed().as_secs_f64() < 3.0) {
            if let Some(max) = options.max_runs {
                if run_count >= max { break; }
            }
            if let Some(p) = prep_cmd { run_command(p, &options.shell, options.show_output); }
            let res = run_command(cmd_str, &options.shell, options.show_output);
            if res.exit_code != 0 && !options.ignore_failure {
                eprintln!("Error: Command terminated with non-zero exit code {}. Use the '-i'/'--ignore-failure' option if you want to ignore this.", res.exit_code);
                std::process::exit(1);
            }
            run_times.push(res);
            if let Some(c) = conclude_cmd { run_command(c, &options.shell, options.show_output); }
            run_count += 1;
        }

        if let Some(cleanup_cmd) = &options.cleanup {
            run_command(cleanup_cmd, &options.shell, options.show_output);
        }

        let (mean, stddev, median, min_time, max_time, user_mean, system_mean) = calculate_stats(&run_times, shell_overhead);

        if run_times.len() > 1 {
            if use_color {
                println!("  Time (\x1b[1;32mmean\x1b[0m \u{00B1} \x1b[32m\u{03C3}\x1b[0m):     \x1b[1;32m{}\x1b[0m \u{00B1} \x1b[32m{}\x1b[0m    [User: \x1b[34m{}\x1b[0m, System: \x1b[34m{}\x1b[0m]", 
                         format_time(mean, &options.time_unit), format_time(stddev, &options.time_unit),
                         format_time(user_mean, &options.time_unit), format_time(system_mean, &options.time_unit));
                println!("  Range (\x1b[36mmin\x1b[0m \u{2026} \x1b[35mmax\x1b[0m):   \x1b[36m{}\x1b[0m \u{2026} \x1b[35m{}\x1b[0m    \x1b[2m{} runs\x1b[0m", 
                         format_time(min_time, &options.time_unit), format_time(max_time, &options.time_unit), run_times.len());
            } else {
                println!("  Time (mean \u{00B1} \u{03C3}):     {} \u{00B1} {}    [User: {}, System: {}]", 
                         format_time(mean, &options.time_unit), format_time(stddev, &options.time_unit),
                         format_time(user_mean, &options.time_unit), format_time(system_mean, &options.time_unit));
                println!("  Range (min \u{2026} max):   {} \u{2026} {}    {} runs", 
                         format_time(min_time, &options.time_unit), format_time(max_time, &options.time_unit), run_times.len());
            }
        } else {
            println!("  Time (abs \u{2261}):        {}               [User: {}, System: {}]", 
                     format_time(mean, &options.time_unit), format_time(user_mean, &options.time_unit), format_time(system_mean, &options.time_unit));
        }
        println!();

        results.push(BenchmarkResult {
            command: cmd_str.to_string(),
            name: name.to_string(),
            runs: run_times,
            mean, stddev, median, min: min_time, max: max_time, user_mean, system_mean,
        });
    }

    if results.len() > 1 {
        show_summary(&results, use_color);
    }

    export_results(&options, &results);
}

fn calculate_stats(runs: &[RunResult], shell_overhead: RunResult) -> (f64, f64, f64, f64, f64, f64, f64) {
    let mut wall_times: Vec<f64> = runs.iter().map(|r| (r.wall_time - shell_overhead.wall_time).max(0.0)).collect();
    let user_times: Vec<f64> = runs.iter().map(|r| (r.user_time - shell_overhead.user_time).max(0.0)).collect();
    let system_times: Vec<f64> = runs.iter().map(|r| (r.system_time - shell_overhead.system_time).max(0.0)).collect();

    let n = wall_times.len() as f64;
    let mean: f64 = wall_times.iter().sum::<f64>() / n;
    let stddev = if n > 1.0 {
        (wall_times.iter().map(|t| (t - mean).powi(2)).sum::<f64>() / (n - 1.0)).sqrt()
    } else {
        0.0
    };

    wall_times.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let median = if wall_times.len() % 2 == 0 {
        (wall_times[wall_times.len()/2 - 1] + wall_times[wall_times.len()/2]) / 2.0
    } else {
        wall_times[wall_times.len()/2]
    };
    let min = wall_times[0];
    let max = wall_times[wall_times.len() - 1];

    let user_mean = user_times.iter().sum::<f64>() / n;
    let system_mean = system_times.iter().sum::<f64>() / n;

    (mean, stddev, median, min, max, user_mean, system_mean)
}

fn show_summary(results: &[BenchmarkResult], use_color: bool) {
    let mut sorted_indices: Vec<usize> = (0..results.len()).collect();
    sorted_indices.sort_by(|&a, &b| results[a].mean.partial_cmp(&results[b].mean).unwrap());

    println!("Summary");
    let fastest = &results[sorted_indices[0]];
    if use_color {
        print!("  \x1b[1;32m{}\x1b[0m ran\n", fastest.name);
    } else {
        println!("  {} ran", fastest.name);
    }

    for &i in &sorted_indices[1..] {
        let current = &results[i];
        let ratio = current.mean / fastest.mean;
        let ratio_stddev = ratio * ((current.stddev / current.mean).powi(2) + (fastest.stddev / fastest.mean).powi(2)).sqrt();
        if use_color {
            println!("    \x1b[1;32m{:.2} \u{00B1} {:.2}\x1b[0m times faster than \x1b[1;34m{}\x1b[0m", ratio, ratio_stddev, current.name);
        } else {
            println!("    {:.2} \u{00B1} {:.2} times faster than {}", ratio, ratio_stddev, current.name);
        }
    }
}

fn export_results(options: &Options, results: &[BenchmarkResult]) {
    if let Some(path) = &options.export_json {
        let mut f = std::fs::File::create(path).unwrap();
        writeln!(f, "{{").unwrap();
        writeln!(f, "  \"results\": [").unwrap();
        for (i, res) in results.iter().enumerate() {
            writeln!(f, "    {{").unwrap();
            writeln!(f, "      \"command\": {:?},", res.command).unwrap();
            writeln!(f, "      \"mean\": {},", res.mean).unwrap();
            writeln!(f, "      \"stddev\": {},", res.stddev).unwrap();
            writeln!(f, "      \"median\": {},", res.median).unwrap();
            writeln!(f, "      \"user\": {},", res.user_mean).unwrap();
            writeln!(f, "      \"system\": {},", res.system_mean).unwrap();
            writeln!(f, "      \"min\": {},", res.min).unwrap();
            writeln!(f, "      \"max\": {},", res.max).unwrap();
            writeln!(f, "      \"times\": {:?},", res.runs.iter().map(|r| r.wall_time).collect::<Vec<_>>()).unwrap();
            writeln!(f, "      \"memory_usage_byte\": {:?},", res.runs.iter().map(|r| r.max_rss).collect::<Vec<_>>()).unwrap();
            writeln!(f, "      \"exit_codes\": {:?}", res.runs.iter().map(|r| r.exit_code).collect::<Vec<_>>()).unwrap();
            write!(f, "    }}{}", if i < results.len() - 1 { "," } else { "" }).unwrap();
        }
        writeln!(f, "  ]").unwrap();
        writeln!(f, "}}").unwrap();
    }
    if let Some(path) = &options.export_csv {
        let mut f = std::fs::File::create(path).unwrap();
        writeln!(f, "command,mean,stddev,median,user,system,min,max").unwrap();
        for res in results {
            writeln!(f, "{},{},{},{},{},{},{},{}", res.command, res.mean, res.stddev, res.median, res.user_mean, res.system_mean, res.min, res.max).unwrap();
        }
    }
    if let Some(path) = &options.export_markdown {
        let mut f = std::fs::File::create(path).unwrap();
        let u = options.time_unit.clone();
        let unit_str = if let Some(un) = &u { match un.as_str() { "millisecond" => "ms", "microsecond" => "µs", _ => "s" } } else { "s" };
        writeln!(f, "| Command | Mean [{}] | Min [{}] | Max [{}] | Relative |", unit_str, unit_str, unit_str).unwrap();
        writeln!(f, "|:---|---:|---:|---:|---:|").unwrap();
        let fastest_mean = results.iter().map(|r| r.mean).min_by(|a, b| a.partial_cmp(b).unwrap()).unwrap();
        for res in results {
            let rel = res.mean / fastest_mean;
            writeln!(f, "| `{}` | {} | {} | {} | {:.2} |", 
                     res.name, format_time(res.mean, &u).split_whitespace().next().unwrap(), 
                     format_time(res.min, &u).split_whitespace().next().unwrap(), 
                     format_time(res.max, &u).split_whitespace().next().unwrap(), rel).unwrap();
        }
    }
    // TODO: implement AsciiDoc and Orgmode exports if needed to match exactly
}
